fn build_rollback_event(health: &RolloutHealthSnapshot, step: &RolloutStep, trace_id: &str) -> GateEvent {
    let message = format!(ROLLBACK_EVENT_TEMPLATE, 
        health.phase, health.observed.instability_score, step.max_instability_score, 
        health.observed.regime_shift_probability, step.max_regime_shift_probability);
