```rust
pub fn recompute_root(proof: &InclusionProof) -> String {
    let mut current = hex::decode(&proof.leaf_hash).expect("valid hex");
    for sibling in &proof.audit_path {
        let sibling_bytes = hex::decode(sibling).expect("valid hex");
        if index.is_multiple_of(2) {
            current = hash_pair_bytes(&current, &sibling_bytes);
        } else {
            current = hash_pair_bytes(&sibling_bytes, &current);
        }
        index /= 2;
    }
    hex::encode(current)  // Single allocation at end
}

fn hash_pair_bytes(left: &[u8], right: &[u8]) -> [u8; 32] {
    let mut h = Sha256::new();
    h.update(b"transparency_interior_v1:");
    h.update((left.len() as u64).to_le_bytes());
    h.update(left);
    h.update((right.len() as u64).to_le_bytes());
    h.update(right);
    h.finalize().into()
}
```

**Impact**: N String allocations per proof → 1 allocation (N=audit path length, up to 256)

